var HABIT=L('{a}は、{b}が考えごとをするとき、必ず左の耳たぶを触ることに気づいた。|{b}は、{a}が嘘をつくとき、少しだけ早口になることを知っていた。今日は、ならなかった。|{a}は、{b}がコーヒーに入れる砂糖の数を、いつの間にか覚えていた。|{b}は、{a}の鼻歌がいつも同じ曲だと気づいて、こっそり笑った。');
var LAZY=L('[m]休日の朝、{a}と{b}は目覚ましをかけずに眠った。起きたのは、昼前だった。|[m]{b}が布団から出ようとすると、{a}が腕をつかんで引き戻した。{a}「休みだから、あと少し｜休みだから、もう少しここにいろ｜休みですから、もう少しここにいてください」|[m]休日の朝、{a}は{b}より先に起きて、二人分のホットケーキを焼いた。');
