if(kn&&T.REASON_KIN)emitT(ctx,[A,B],'bond',FC.fresh(ctx,T.REASON_KIN),sp+'同居の理由：'+kn.label+'の二人の同居',{rel:kn.label},'meet');
else emitT(ctx,[A,B],'bond',FC.fresh(ctx,s0===0?R.s:R.f),sp+'同居の理由：'+R.label+(s0===0?'（知らない人どうし）':''),null,'meet');
