if(fp)emitT(ctx,fp,'bond',FC.fresh(ctx,(T.FIRSTNIGHT||{})[fk&&T.FIRSTNIGHT.k?'k':FC.st(ctx,fp[0],fp[1])===0?'s':'f']),FC.W(ctx,'自宅')+'同居の最初の夜',fk?{rel:fk.label}:null,null);
